#include "stdlib/math/base/special/binetf.h"
#include "stdlib/math/base/assert/is_nanf.h"
#include "stdlib/math/base/special/cospif.h"
#include "stdlib/math/base/special/powf.h"
#include "stdlib/constants/float32/phi.h"
#include "stdlib/constants/float32/pinf.h"
#include "stdlib/constants/float32/ninf.h"

static const float SQRT_5 = 2.23606797749979f;

/**
* Evaluates Binet's formula extended to real numbers for single precision floating-point number.
*
* ## Notes
*
* -   [Non integer Fibonacci numbers][1]
* -   [Interpolated Fibonacci numbers - real or complex][2]
*
* [1]: https://math.stackexchange.com/questions/798190/non-integer-fibonacci-numbers
* [2]: https://math.stackexchange.com/questions/589841/interpolated-fibonacci-numbers-real-or-complex
*
* @param x    input value
* @return     real-valued result
*
* @example
* float y = stdlib_base_binetf( 2.0f );
* // returns 1.0f
*/
float stdlib_base_binetf( const float x ) {
	float a;
	float b;

	if ( stdlib_base_is_nanf( x ) || x == STDLIB_CONSTANT_FLOAT32_PINF || x == STDLIB_CONSTANT_FLOAT32_NINF ) {
		return 0.0f / 0.0f; // NaN
	}
	a = stdlib_base_powf( STDLIB_CONSTANT_FLOAT32_PHI, x );
	b = stdlib_base_cospif( x ) / a;
	return ( a - b ) / SQRT_5;
}
